class Participant { String name,team; boolean registered; Participant(String n,String t){name=n;team=t;registered=true;} Participant(String n){this(n,"Unassigned");} void printStatus(){System.out.println(name+" | "+team+" | Registered: "+registered);} } public class HackathonRegistration { public static void main(String[] a){String[] n={"Ravi","Meera"},t={"ByteBusters",""};for(int i=0;i<n.length;i++){Participant p=t[i].isEmpty()?new Participant(n[i]):new Participant(n[i],t[i]);p.printStatus();}} }
